if(!titles['amc-reminders']){titles['amc-reminders']='AMC Expiry Reminders';let operations=groups.find(g=>g[0]==='OPERATIONS')[1],index=operations.findIndex(m=>m[0]==='service-reminders');operations.splice(index+1,0,['amc-reminders','AMC Expiry Reminders','shield']);let service=operations.find(m=>m[0]==='service-reminders');if(service)service[1]='Vehicle Service Reminders'}
